 Jersey:Object.freeze({Dairy:1.30*1.05,Produce:1.24*1.05,'Meat & fish':1.20*1.05,Bakery:1.25*1.05,Cupboard:1.10*1.05}),
 US:Object.freeze({Dairy:1.65,Produce:1.80,'Meat & fish':1.70,Bakery:1.80,Cupboard:1.50})
